/**
 * Every plugin tool must declare an input schema whose root type is "object".
 *
 * MCP clients validate tools/call arguments against inputSchema, and the MCP
 * spec requires the root of that schema to be an object. A tool with a missing
 * schema, or a root type of "string", "array", etc., is rejected by strict
 * hosts and cannot be called with named arguments. The catalog is generated by
 * `bun run gen:tool-catalog` and committed as servers/_tool-catalog.json; this
 * test loads that file and fails on any tool whose schema is not a root object
 * schema. The validator is also exercised on synthetic input so a regression in
 * the validator itself cannot pass silently.
 */

import { describe, expect, test } from "bun:test";
import catalog from "../servers/_tool-catalog.json" with { type: "json" };

interface SchemaTool {
  name: unknown;
  inputSchema: unknown;
}

/**
 * Describe each tool whose inputSchema is missing, not a plain object, or
 * whose root `type` is not exactly "object". Returns one line per problem.
 */
function invalidInputSchemas(tools: readonly SchemaTool[]): string[] {
  return tools.flatMap((tool) => {
    const label = String(tool.name);
    const schema = tool.inputSchema;
    if (schema === undefined || schema === null) {
      return [`${label}: inputSchema is missing`];
    }
    if (typeof schema !== "object" || Array.isArray(schema)) {
      return [`${label}: inputSchema is not an object`];
    }
    const type = (schema as { type?: unknown }).type;
    if (type !== "object") {
      return [`${label}: inputSchema.type is ${JSON.stringify(type) ?? "missing"}, expected "object"`];
    }
    return [];
  });
}

describe("plugin tool catalog input schemas", () => {
  test("catalog is non-empty", () => {
    expect(catalog.length).toBeGreaterThan(0);
  });

  test("every tool has an inputSchema whose root type is object", () => {
    expect(invalidInputSchemas(catalog)).toEqual([]);
  });

  test("validator accepts object schemas and reports missing or non-object ones", () => {
    expect(
      invalidInputSchemas([{ name: "ok", inputSchema: { type: "object", properties: {} } }]),
    ).toEqual([]);
    expect(invalidInputSchemas([{ name: "missing", inputSchema: undefined }])).toEqual([
      "missing: inputSchema is missing",
    ]);
    expect(invalidInputSchemas([{ name: "nil", inputSchema: null }])).toEqual([
      "nil: inputSchema is missing",
    ]);
    expect(invalidInputSchemas([{ name: "arr", inputSchema: [] }])).toEqual([
      "arr: inputSchema is not an object",
    ]);
    expect(invalidInputSchemas([{ name: "str", inputSchema: "object" }])).toEqual([
      "str: inputSchema is not an object",
    ]);
    expect(invalidInputSchemas([{ name: "untyped", inputSchema: {} }])).toEqual([
      'untyped: inputSchema.type is missing, expected "object"',
    ]);
    expect(invalidInputSchemas([{ name: "wrong", inputSchema: { type: "array" } }])).toEqual([
      'wrong: inputSchema.type is "array", expected "object"',
    ]);
  });
});
